/**
 * @name Path Traversal from Parameters
 * @description Traces flow from function parameters to file system access.
 * @kind path-problem
 * @problem.severity warning
 * @id py/path-traversal-param
 * @tags security
 *       external/cwe/cwe-022
 *       external/cwe/cwe-073
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.Concepts

module PathTraversalConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    // Consider all parameters of public functions as potential sources
    exists(Function f, DataFlow::ParameterNode p |
      f.getName().matches("%") and // match all functions
      not f.getName().matches("_%") and // exclude private functions (heuristic)
      p.getParameter() = f.getArg(_) and
      source = p
    )
  }

  predicate isSink(DataFlow::Node sink) {
    sink = any(FileSystemAccess fa).getAPathArgument()
  }
}

module PathTraversalFlow = TaintTracking::Global<PathTraversalConfig>;
import PathTraversalFlow::PathGraph

from PathTraversalFlow::PathNode source, PathTraversalFlow::PathNode sink
where PathTraversalFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "File system access from parameter $@.", source.getNode(), source.getNode().toString()

/**
 * @name Path traversal in joinpath
 * @description Detects flow from function parameters to pathlib.Path.joinpath, which could lead to path traversal.
 * @kind problem
 * @problem.severity warning
 * @id py/path-traversal-joinpath
 * @tags security
 *       external/cwe/cwe-022
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.ApiGraphs

module PathTraversalConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    source instanceof DataFlow::ParameterNode
  }

  predicate isSink(DataFlow::Node sink) {
    exists(DataFlow::CallCfgNode call |
      call = API::moduleImport("pathlib").getMember("Path").getMember("joinpath").getACall() or
      call.asExpr().(Attribute).getAttr() = "joinpath"
      |
      sink = call.getArg(_)
    )
  }
}

module PathTraversalFlow = TaintTracking::Global<PathTraversalConfig>;

from DataFlow::Node source, DataFlow::Node sink
where PathTraversalFlow::flow(source, sink)
select sink, "Potential path traversal from parameter $@", source, source.toString()

/**
 * @name Potential Path Traversal in Library
 * @description detects flow from public method parameters to path joining operations which might allow traversal
 * @kind path-problem
 * @problem.severity warning
 * @id py/lib-path-traversal
 * @tags security
 *       external/cwe/cwe-022
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.ApiGraphs

module PathTraversalConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    // Parameters of public methods in the main package
    exists(Function f, DataFlow::ParameterNode p |
      f.getName().matches("%") and
      not f.getName().matches("_%") and
      p.getParameter() = f.getArg(_) and
      source = p and
      f.getScope().getEnclosingModule().getName().matches("importlib_metadata%")
    )
  }

  predicate isSink(DataFlow::Node sink) {
    // Sinks: arguments to joinpath, os.path.join, open
    exists(DataFlow::CallCfgNode call |
      (
        call.getFunction().(DataFlow::AttrRead).getAttributeName() = "joinpath" or
        call = API::moduleImport("os").getMember("path").getMember("join").getACall() or
        call = API::builtin("open").getACall()
      ) and
      sink = call.getArg(_)
    )
  }
}

module PathTraversalFlow = TaintTracking::Global<PathTraversalConfig>;
import PathTraversalFlow::PathGraph

from PathTraversalFlow::PathNode source, PathTraversalFlow::PathNode sink
where PathTraversalFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "Potential path traversal from parameter $@.", source.getNode(), "parameter"
